(function ($) {
    $.fn.buttonLoader = function (action) {
        var $button = $(this);

        if (action === "start") {
            if ($button.attr("disabled") === "disabled") return false;

            $button.attr("data-btn-text", $button.text());
            var loadingText = $button.attr("data-load-text") || "Loading";

            $button.html(
                '<span class="spinner"><i class="fal fa-spinner fa-spin" title="button-loader"></i></span> ' +
                loadingText
            );
            $button.addClass("active").attr("disabled", true);
        }

        if (action === "stop") {
            $button.html($button.attr("data-btn-text"));
            $button.removeClass("active").attr("disabled", false);
        }
    };
})(jQuery);
